// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.concurrent.Callable;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Consumer;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

/**
 * {@link AdjacencyApplier#idle()} is read lock-free by test seams such as
 * {@link LmdbDirectAdjacencyStore#buildNowForTest()}. Starting a requested rebuild raises {@code buildInFlight} before
 * dropping {@code rebuildRequested}; a concurrent reader must never observe neither, or a caller that requested a
 * rebuild returns while the previous base is still published.
 */
@Timeout(120)
class AdjacencyApplierIdleTest {

	// the window is two adjacent volatile writes, so one round rarely hits it; a broken read order is still seen
	// within a few tens of thousands of rounds, and the loop stops at the first observation
	private static final int ROUNDS = 250_000;

	@Test
	@SuppressWarnings("unchecked")
	void idleIsNeverObservedWhileARequestedRebuildStarts() throws Exception {
		HeldWorkerPool workers = new HeldWorkerPool();
		SteppingApplierScheduler scheduler = new SteppingApplierScheduler();
		AdjacencyIndexOps<Object, Object, Object> ops = mock(AdjacencyIndexOps.class);
		when(ops.build(any())).thenAnswer(call -> new AdjacencyIndexOps.Candidate<>(new Object(), null, 0, 0));
		when(ops.secondBaseFits(any())).thenReturn(true);
		AdjacencyApplier<Object, Object, Object> applier = new AdjacencyApplier<>(new AdjacencyCommitLog(0), ops,
				(base, overlays, index) -> null, workers, scheduler, Long.MAX_VALUE, 1000);
		applier.start();

		AtomicBoolean armed = new AtomicBoolean();
		AtomicBoolean done = new AtomicBoolean();
		AtomicLong probes = new AtomicLong();
		AtomicLong idleWhileStarting = new AtomicLong();
		Thread prober = new Thread(() -> {
			while (!done.get()) {
				boolean starting = armed.get();
				if (applier.idle() && starting) {
					idleWhileStarting.incrementAndGet();
				}
				probes.incrementAndGet();
			}
		}, "adjacency-idle-prober");
		prober.setDaemon(true);
		prober.start();
		try {
			for (int round = 0; round < ROUNDS && idleWhileStarting.get() == 0; round++) {
				applier.requestRebuild();
				assertThat(scheduler.step()).as("the request unit runs").isTrue();
				assertThat(applier.idle()).as("a requested rebuild is not idle").isFalse();

				armed.set(true);
				awaitProbes(probes, 2);
				assertThat(scheduler.step()).as("the rebuild starts").isTrue();
				assertThat(applier.buildInFlight()).isTrue();
				awaitProbes(probes, 2);
				armed.set(false);
				// the probe that may have read armed=true must finish before the build is allowed to complete
				awaitProbes(probes, 2);

				workers.completeHeld();
				scheduler.drain();
				assertThat(applier.idle()).as("the published rebuild leaves the applier idle").isTrue();
				assertThat(applier.state().status()).isEqualTo(AdjacencyState.Status.SERVING);
			}
		} finally {
			done.set(true);
			prober.join();
			applier.requestClose();
			scheduler.drain();
			applier.close();
		}
		assertThat(idleWhileStarting.get())
				.as("idle() observed while a requested rebuild was starting")
				.isZero();
	}

	private static void awaitProbes(AtomicLong probes, long count) {
		long target = probes.get() + count;
		while (probes.get() < target) {
			Thread.onSpinWait();
		}
	}

	/** Holds each submitted task until the test completes it on its own thread. */
	private static final class HeldWorkerPool implements AdjacencyWorkerPool {
		private Runnable held;

		@Override
		public <T> void submit(Callable<T> work, Consumer<Outcome<T>> onDone) {
			assertThat(held).as("one task in flight at a time").isNull();
			held = () -> {
				Outcome<T> outcome;
				try {
					outcome = Outcome.success(work.call());
				} catch (Exception e) {
					outcome = Outcome.failure(e);
				}
				onDone.accept(outcome);
			};
		}

		void completeHeld() {
			Runnable task = held;
			held = null;
			assertThat(task).as("a held task").isNotNull();
			task.run();
		}

		@Override
		public void shutdown() {
		}
	}
}
